DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT122-S4-Q6$batch02$ AND q.stimulus=$batch02$The simultaneous and apparently independent development in several ancient cultures of a myth of creatures who were half human and half horse parallels the increased use of horses in these cultures. But despite the nobility and gentleness traditionally ascribed to the horse, the mythical half-horse, half-humans were frequently portrayed as violent and savage. Many human cultures use myth to express unconscious thoughts, so these mythical creatures obviously reflect people’s unconscious fear of the horse.$batch02$ AND q.prompt=$batch02$The reasoning in the argument is flawed because the argument$batch02$ AND q.correct_choice=$batch02$A$batch02$) THEN RAISE EXCEPTION 'Question changed: PT122-S4-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch02$PT122-S4-Q6$batch02$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S4-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT122-S4-Q6$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$The violent half-horse, half-human creatures reflect people's unconscious fear of the horse.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$The myths arose as these cultures used horses more. The creatures were savage even though horses were thought noble and gentle. Many cultures use myth to express unconscious thoughts.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Grant that the myth expresses some unconscious fear. Fear of *what*? The creature is half human. It might stand for a person on horseback: the mounted raiders who arrived as horses spread. Then the myth would reflect fear of armed riders, not of horses. The argument assumes the creature means "horse" without showing it.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the gap between "the creature is part horse" and "the creature stands for the horse."$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT122-S4-Q6$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$For the creatures to reveal a fear *of the horse*, they must represent the horse in people's minds. They might represent people, riders or something else entirely. The argument never shows which, yet its conclusion depends on it.$batch02$), ($batch02$B$batch02$, $batch02$Whether the fear is reasonable does not matter. A fear can be both justified and unconscious. This would not cast doubt on the claim that the myth expresses that fear.$batch02$), ($batch02$C$batch02$, $batch02$The argument speaks only of myths *expressing* unconscious thoughts. It never mentions suppression, so it cannot confuse the two.$batch02$), ($batch02$D$batch02$, $batch02$The stimulus calls the developments "apparently independent." Even if one culture borrowed the myth, the borrowed version could still express fear of horses. Borrowing does not touch the gap between creature and horse.$batch02$), ($batch02$E$batch02$, $batch02$The argument relies on the fact that myths express unconscious thoughts. It does not need to explain *why* they do. An answer asking for more explanation of a premise is not the flaw.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT122-S4-Q6$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
